const job = $('Fetch Job').first().json;
const candidates = $('Fetch Candidates').all().map(item => item.json);
const triggeredBy = $('Webhook').first().json.body.triggered_by;

const candidateList = candidates.map(c => ({
  id: c.id,
  name: c.full_name,
  discipline: c.discipline,
  discipline_other: c.discipline_other,
  location: c.location_text,
  years_experience: c.years_experience,
  salary_expectation: c.salary_expectation,
  work_authorisation: c.work_auth,
  headline: c.headline,
  summary: c.summary_self,
  strengths: c.strengths,
  concerns: c.concerns_or_gaps,
  best_fit_roles: c.best_fit_role_types,
  availability: c.availability_signal,
  niche_score: c.niche_match_score
}));

const systemPrompt = `You are a senior technical recruitment consultant with deep expertise across engineering disciplines. You assess candidate suitability for roles based on their full profile — not just their primary discipline.

A candidate may be highly suitable for roles outside their listed discipline if their experience, education, or transferable skills indicate capability. For example, an Electronic Engineer with 3 years of PCB design experience may be highly suitable for an Embedded Systems role even if their listed discipline is "Electronic Engineering" rather than "Embedded Systems".

Score each candidate 0-100 against the job specification:
- 0-20: Poor fit, significant gaps
- 21-40: Weak fit, some transferable skills
- 41-60: Moderate fit, could work with development
- 61-80: Good fit, meets most requirements
- 81-100: Strong fit, closely matches requirements

Scoring breakdown (use this internally, do not output):
- Technical capability and discipline relevance: 0-35
- Experience level and seniority match: 0-25
- Location and work authorisation fit: 0-20
- Salary alignment: 0-10
- Career trajectory and role type fit: 0-10

Return ONLY a valid JSON array. No markdown, no explanation, no preamble:
[
  {
    "candidate_id": "uuid-here",
    "score": 85,
    "reasoning": "2-3 sentences on why they are a good fit, referencing specific experience",
    "concerns": "1-2 sentences on gaps or risks, or null if none"
  }
]`;

const userPrompt = `JOB SPECIFICATION:
Title: ${job.role_title}
Company: ${job.company_name ?? job.inferred_client_name ?? 'Confidential'}
Discipline: ${job.discipline}
Location: ${job.location_city ?? ''}, ${job.location_state ?? ''}
Salary Range: ${job.salary_min_aud ? '$' + job.salary_min_aud + ' - $' + job.salary_max_aud + ' AUD' : 'Not specified'}
Role requirements: ${job.employee_instruction ?? 'Not specified'}
Pain hypothesis: ${job.pain_hypothesis ?? 'Not specified'}
Recommended service: ${job.recommended_service ?? 'Not specified'}

CANDIDATES TO ASSESS:
${JSON.stringify(candidateList, null, 2)}

Assess all ${candidateList.length} candidates against this job. Return scores for every candidate listed.`;

return [{
  json: {
    systemPrompt,
    userPrompt,
    job,
    candidates,
    triggeredBy,
    jobId: job.id
  }
}];

const responseData = $('Claude AI Scoring').first().json;
const promptData = $('Build Prompt').first().json;

// Claude response comes back with content array
const rawText = responseData.content
  .filter(block => block.type === 'text')
  .map(block => block.text)
  .join('');

// Strip markdown fences
const cleaned = rawText
  .replace(/```json\n?/g, '')
  .replace(/```\n?/g, '')
  .trim();

const scores = JSON.parse(cleaned);

return scores.map(score => ({
  json: {
    candidate_id: score.candidate_id,
    job_id: promptData.jobId,
    score: score.score,
    reasoning: score.reasoning ?? null,
    concerns: score.concerns ?? null,
    triggered_by: promptData.triggeredBy
  }
}));

const data = $('Build Prompt').first().json;

const body = {
  model: "claude-sonnet-4-5",
  max_tokens: 4000,
  system: data.systemPrompt,
  messages: [
    {
      role: "user",
      content: data.userPrompt
    }
  ]
};

return [{
  json: {
    body: JSON.stringify(body),
    jobId: data.jobId,
    candidates: data.candidates,
    triggeredBy: data.triggeredBy
  }
}];
